(() => { window.GravewrightSDK.register({id:"semantic-dragdrop-e2e",async ready(sdk){
  await sdk.scene.objectTypes.register({typeId:"semantic-dragdrop-e2e.board-zone",schemaVersion:1,displayName:"Board Zone",dataSchema:{type:"object"},geometryKinds:["rect"],visualDefinition:[{kind:"shape"}],interactionDefinitions:[]});
  await sdk.scene.objectTypes.register({typeId:"semantic-dragdrop-e2e.scene-pin",schemaVersion:1,displayName:"Journal Pin",dataSchema:{type:"object",properties:{linkedContent:{type:"object",format:"content-reference"}},required:["linkedContent"],additionalProperties:false},geometryKinds:["point"],visualDefinition:[{kind:"icon"},{kind:"label"}],interactionDefinitions:[{id:"open",label:"Open"}]});
  await sdk.ui.dragDrop.registerSource({id:"card-source",referenceKinds:["card"],operations:["place"],schemaVersion:1});
  await sdk.ui.dragDrop.registerSource({id:"item-source",referenceKinds:["item"],operations:["copy"],schemaVersion:1});
  await sdk.ui.dragDrop.registerSource({id:"journal-source",referenceKinds:["journal"],operations:["link"],schemaVersion:1});
  await sdk.ui.dragDrop.registerTarget({id:"board-zone-target",surface:"board-zone",targetKinds:["scene-object"],worldObjectTypeId:"semantic-dragdrop-e2e.board-zone",operations:["place"],actionReference:"semantic-dragdrop-e2e:place-card@1",schemaVersion:1});
  await sdk.ui.dragDrop.registerTarget({id:"actor-target",surface:"core-resource",targetKinds:["actor"],operations:["copy"],actionReference:"semantic-dragdrop-e2e:insert-item@1",schemaVersion:1});
  await sdk.ui.dragDrop.registerTarget({id:"scene-target",surface:"scene-world-object",targetKinds:["scene-surface"],operations:["link"],actionReference:"semantic-dragdrop-e2e:create-pin@1",schemaVersion:1});
  sdk.events.on("scene.object.interacted",async event=>{document.body.dataset.sceneRuntimePinInteraction="received";try{const object=await sdk.scene.objects.get(event.resource.id);if(object?.typeId==="semantic-dragdrop-e2e.scene-pin"){await sdk.content.open(object.data.linkedContent);document.body.dataset.sceneRuntimePinInteraction="opened";}}catch(error){document.body.dataset.sceneRuntimePinInteraction=`error:${error.message}`;}});
  sdk.ui.slots.register("dock.actions",host=>{const button=document.createElement("button");button.type="button";button.dataset.testid="scene-runtime-create-zone";button.textContent="Create zone";button.onclick=()=>sdk.scene.objects.create(sdk.game.scene().id,{typeId:"semantic-dragdrop-e2e.board-zone",geometry:{kind:"rect",x:900,y:450,width:140,height:140},presentation:{label:"Drop zone",fill:"#334455"},audience:{kind:"campaign"}});host.append(button);});
}}); })();
